import functools


def retry(max_attempts: int = 3, exceptions: tuple = (Exception,)):
    """Decorator factory: retry the wrapped function on the given exceptions."""
    if max_attempts < 1:
        raise ValueError("max_attempts must be >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == max_attempts:
                        raise
        return wrapper
    return decorator


# ---------------------------------------------------------------------------
# Test harness (do not change). The tests call simulate(...).
# It decorates a flaky "API call" with your retry decorator and reports
# what happened.
# ---------------------------------------------------------------------------
def simulate(fail_times: int, max_attempts: int, error: str = "ConnectionError") -> dict:
    exc_cls = {"ConnectionError": ConnectionError, "TimeoutError": TimeoutError, "ValueError": ValueError}[error]
    calls = {"n": 0}

    @retry(max_attempts=max_attempts, exceptions=(ConnectionError, TimeoutError))
    def fetch_page():
        """Fetch one page from the marketplace API."""
        calls["n"] += 1
        if calls["n"] <= fail_times:
            raise exc_cls(f"attempt {calls['n']} failed")
        return "ok"

    try:
        result = fetch_page()
        return {"result": result, "calls": calls["n"], "name": fetch_page.__name__}
    except (ConnectionError, TimeoutError, ValueError) as e:
        return {"error": type(e).__name__, "calls": calls["n"], "name": fetch_page.__name__}
